def save_raw_data(self, obj, filename, gzip):
        """
        Saves data to HDF5 file.

        Parameters
        ----------
        obj : pyblock.BeamBlockMultiVolume
            BeamBlockMultiVolume object to save to file
        filename : str
            Path and name of file to save data too. If this file exists it will
            be removed first.
        gzip : bool
            True - Save file will be gzipped, removing previous gzipped file if
                   it exists.

            False - Save file will not be compressed.

        """
        if filename is None:
            filename = './temporary_block_data.h5'
        os.system('rm ' + filename)
        h = h5py.File(filename)
        v = getattr(obj, 'Azimuth')
        h.create_dataset('Azimuth', data=np.array(v), dtype=np.array(v).dtype)
        for var in ['rain_refl', 'drizz_zdr']:
            for k, v in getattr(obj, var).items():
                h.create_dataset(var + '_' + k, data=np.array(v), dtype=float)
        for var in ['DZ', 'DR', 'KD']:
            for k, v in obj.fsc_data[var].items():
                h.create_dataset('fsc_data_' + var.lower() + k,
                                 data=np.array(v), dtype=float)
        h.close()
        if gzip:
            os.system('rm ' + filename + '.gz')
            os.system('gzip ' + filename)
def load_raw_data(self, filename, gzip):
        """
        Loads data from HDF5 file.

        Parameters
        ----------
        filename : str
            Full path and name of file that hosts BeamBlockMultiVolume data.
        gzip : bool
            True - File to be loaded is gzipped.

            False - File to be loaded is not gzipped

        """
        if filename is None:
            filename = './temporary_block_data.h5'
        if gzip:
            os.system('gzip -d ' + filename + '.gz')
        h = h5py.File(filename, 'r')
        self.Azimuth = np.array(h['Azimuth'])
        for var in ['rain_refl', 'drizz_zdr']:
            v = {}
            cnt = 0
            for key in h.keys():
                if str(key)[:9] == var:
                    cnt += 1
            for i in range(cnt):
                v[str(i)] = np.array(h[var + '_' + str(i)])
            setattr(self, var, v)
        self.fsc_data = {}
        for var in ['DZ', 'KD', 'DR']:
            cnt = 0
            self.fsc_data[var] = {}
            for key in h.keys():
                if str(key)[:11] == 'fsc_data_' + var.lower():
                    cnt += 1
            for i in range(cnt):
                self.fsc_data[var][str(i)] = np.array(
                    h['fsc_data_' + var.lower() + str(i)])
        h.close()
        if gzip:
            os.system('gzip  ' + filename)

def makepasv(self):
        if self.af == socket.AF_INET:
            host, port = parse227(self.sendcmd('PASV'))
        else:
            host, port = parse229(self.sendcmd('EPSV'), self.sock.getpeername())
        return host, port

def makepasv(self):
        """Internal: Does the PASV or EPSV handshake -> (address, port)"""
        if self.af == socket.AF_INET:
            untrusted_host, port = parse227(self.sendcmd('PASV'))
            if self.trust_server_pasv_ipv4_address:
                host = untrusted_host
            else:
                host = self.sock.getpeername()[0]
        else:
            host, port = parse229(self.sendcmd('EPSV'), self.sock.getpeername())
        return host, port

def _get_cert_url(self):
        """
        Get the signing certificate URL.
        Only accept urls that match the domains set in the
        AWS_SNS_EVENT_CERT_TRUSTED_DOMAINS setting. Sub-domains
        are allowed. i.e. if amazonaws.com is in the trusted domains
        then sns.us-east-1.amazonaws.com will match.
        """
        cert_url = self._data.get("SigningCertURL")
        if not cert_url:
            logger.warning('No signing certificate URL: "%s"', cert_url)
            return None

        if not cert_url.startswith("https://"):
            logger.warning('Untrusted certificate URL: "%s"', cert_url)
            return None

        url_obj = urlparse(cert_url)
        for trusted_domain in settings.EVENT_CERT_DOMAINS:
            parts = trusted_domain.split(".")
            if "amazonaws.com" in trusted_domain:
                if not SES_REGEX_CERT_URL.match(cert_url):
                    if len(parts) < 4:
                        return None
                    else:
                        logger.warning('Possible security risk for: "%s"', cert_url)
                        logger.warning(
                            "It is strongly recommended to configure the full domain in EVENT_CERT_DOMAINS. "
                            "See v3.5.0 release notes for more details."
                        )

            if url_obj.netloc.split(".")[-len(parts) :] == parts:
                return cert_url

        return None
